begin;
set transaction isolation level repeatable read read only;
set local search_path=pg_catalog,public;
set local timezone='UTC';
set local datestyle='ISO, YMD';
set local extra_float_digits=3;
set local statement_timeout=60000;
select jsonb_build_object('projectId',current_setting('neon.project_id',true),'branchId',current_setting('neon.branch_id',true),'database',current_database(),'role',current_user,'serverVersion',current_setting('server_version'),'transactionReadOnly',current_setting('transaction_read_only'),'transactionIsolation',current_setting('transaction_isolation'),'capturedAt',clock_timestamp(),'ownerBypassRls',(select rolbypassrls from pg_roles where rolname=current_user),'rlsActiveForReadTables',(select count(*)::int from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema' and c.relkind in('r','p','m') and row_security_active(c.oid)),'currentStoredTableCount',(select count(*)::int from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema' and c.relkind in('r','p','m','f'))) as identity;
select jsonb_agg(to_jsonb(c) order by category) as catalog from (select 'namespaces' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select n.nspname,r.rolname as owner from pg_namespace n join pg_roles r on r.oid=n.nspowner where n.nspname !~ '^pg_' and n.nspname <> 'information_schema' order by n.nspname) q union all select 'enums' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select t.typname,e.enumlabel,e.enumsortorder from pg_type t join pg_enum e on e.enumtypid=t.oid where t.typnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') order by t.typname,e.enumsortorder) q union all select 'domains' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select t.typname,format_type(t.typbasetype,t.typtypmod) as base,t.typnotnull,t.typdefault from pg_type t where t.typnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') and t.typtype='d' order by t.typname) q union all select 'extensions' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select e.extname,e.extversion,n.nspname as schema from pg_extension e join pg_namespace n on n.oid=e.extnamespace order by e.extname) q union all select 'tables' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (c.relnamespace::regnamespace::text||'.'||c.relname),c.relkind,c.relpersistence,c.relrowsecurity,c.relforcerowsecurity,r.rolname as owner,c.reloptions,pg_get_partkeydef(c.oid) as partition_key from pg_class c join pg_roles r on r.oid=c.relowner where c.relnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') and c.relkind in('r','p','v','m','S','f') order by (c.relnamespace::regnamespace::text||'.'||c.relname)) q union all select 'columns' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (c.relnamespace::regnamespace::text||'.'||c.relname),(row_number() over(partition by (c.relnamespace::regnamespace::text||'.'||c.relname) order by a.attnum))::int as ordinal_position,a.attname,format_type(a.atttypid,a.atttypmod) as type,a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid) as default_expression,case when a.attcollation=0 then null else cn.nspname||'.'||co.collname end as collation from pg_attribute a join pg_class c on c.oid=a.attrelid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum left join pg_collation co on co.oid=a.attcollation left join pg_namespace cn on cn.oid=co.collnamespace where c.relnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') and c.relkind in('r','p','v','m','f') and a.attnum>0 and not a.attisdropped order by (c.relnamespace::regnamespace::text||'.'||c.relname),a.attnum) q union all select 'constraints' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select c.conname,coalesce((r.relnamespace::regnamespace::text||'.'||r.relname),'') as relation,c.contype,c.convalidated,c.condeferrable,c.condeferred,pg_get_constraintdef(c.oid,false) as definition from pg_constraint c left join pg_class r on r.oid=c.conrelid where c.connamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') order by relation,c.conname) q union all select 'indexes' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (t.relnamespace::regnamespace::text||'.'||t.relname) as relation,(i.relnamespace::regnamespace::text||'.'||i.relname) as name,x.indisunique,x.indisprimary,x.indisvalid,x.indisready,x.indimmediate,x.indnullsnotdistinct,pg_get_indexdef(i.oid) as definition from pg_index x join pg_class i on i.oid=x.indexrelid join pg_class t on t.oid=x.indrelid where t.relnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') order by (t.relnamespace::regnamespace::text||'.'||t.relname),(i.relnamespace::regnamespace::text||'.'||i.relname)) q union all select 'policies' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check from pg_policies where schemaname in (select nspname from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') order by tablename,policyname) q union all select 'functions' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (p.pronamespace::regnamespace::text||'.'||p.proname),pg_get_function_identity_arguments(p.oid) as arguments,r.rolname as owner,p.prosecdef,p.proleakproof,p.provolatile,p.proparallel,p.proconfig,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_roles r on r.oid=p.proowner where p.pronamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') and p.prokind in('f','p') order by (p.pronamespace::regnamespace::text||'.'||p.proname),arguments) q union all select 'triggers' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (c.relnamespace::regnamespace::text||'.'||c.relname) as relation,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,false) as definition from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') and not t.tgisinternal order by (c.relnamespace::regnamespace::text||'.'||c.relname),t.tgname) q union all select 'views' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (c.relnamespace::regnamespace::text||'.'||c.relname),pg_get_viewdef(c.oid,false) as definition from pg_class c where c.relnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') and c.relkind in('v','m') order by (c.relnamespace::regnamespace::text||'.'||c.relname)) q union all select 'roles' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select rolname,rolcanlogin,rolinherit,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolconnlimit,rolconfig from pg_roles where rolname !~ '^pg_' order by rolname) q union all select 'memberships' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select parent.rolname as parent,member.rolname as member,grantor.rolname as grantor,m.admin_option,m.inherit_option,m.set_option from pg_auth_members m join pg_roles parent on parent.oid=m.roleid join pg_roles member on member.oid=m.member join pg_roles grantor on grantor.oid=m.grantor order by parent.rolname,member.rolname,grantor.rolname) q union all select 'relationGrants' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (c.relnamespace::regnamespace::text||'.'||c.relname),case when a.grantee=0 then 'PUBLIC' else grantee.rolname end as grantee,grantor.rolname as grantor,a.privilege_type,a.is_grantable from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))) a left join pg_roles grantee on grantee.oid=a.grantee join pg_roles grantor on grantor.oid=a.grantor where c.relnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') and c.relkind in('r','p','v','m','S','f') order by (c.relnamespace::regnamespace::text||'.'||c.relname),grantee,grantor,a.privilege_type) q union all select 'columnGrants' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (c.relnamespace::regnamespace::text||'.'||c.relname),col.attname,case when a.grantee=0 then 'PUBLIC' else grantee.rolname end as grantee,grantor.rolname as grantor,a.privilege_type,a.is_grantable from pg_attribute col join pg_class c on c.oid=col.attrelid cross join lateral aclexplode(col.attacl) a left join pg_roles grantee on grantee.oid=a.grantee join pg_roles grantor on grantor.oid=a.grantor where c.relnamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') and col.attnum>0 and not col.attisdropped order by (c.relnamespace::regnamespace::text||'.'||c.relname),col.attname,grantee,grantor,a.privilege_type) q union all select 'functionGrants' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select (p.pronamespace::regnamespace::text||'.'||p.proname),pg_get_function_identity_arguments(p.oid) as arguments,case when a.grantee=0 then 'PUBLIC' else grantee.rolname end as grantee,grantor.rolname as grantor,a.privilege_type,a.is_grantable from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a left join pg_roles grantee on grantee.oid=a.grantee join pg_roles grantor on grantor.oid=a.grantor where p.pronamespace in (select oid from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') order by (p.pronamespace::regnamespace::text||'.'||p.proname),arguments,grantee,grantor,a.privilege_type) q union all select 'schemaGrants' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select n.nspname,owner.rolname as owner,case when a.grantee=0 then 'PUBLIC' else grantee.rolname end as grantee,grantor.rolname as grantor,a.privilege_type,a.is_grantable from pg_namespace n join pg_roles owner on owner.oid=n.nspowner cross join lateral aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a left join pg_roles grantee on grantee.oid=a.grantee join pg_roles grantor on grantor.oid=a.grantor where n.nspname in (select nspname from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') order by grantee,grantor,a.privilege_type) q union all select 'defaultGrants' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select owner.rolname as owner,coalesce(n.nspname,'ALL_SCHEMAS') as schema,d.defaclobjtype,case when a.grantee=0 then 'PUBLIC' else grantee.rolname end as grantee,grantor.rolname as grantor,a.privilege_type,a.is_grantable from pg_default_acl d join pg_roles owner on owner.oid=d.defaclrole left join pg_namespace n on n.oid=d.defaclnamespace left join lateral aclexplode(d.defaclacl) a on true left join pg_roles grantee on grantee.oid=a.grantee left join pg_roles grantor on grantor.oid=a.grantor order by owner.rolname,schema,d.defaclobjtype,grantee,grantor,a.privilege_type) q union all select 'sequences' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select schemaname,sequencename,sequenceowner,data_type,start_value,min_value,max_value,increment_by,cycle,cache_size,last_value from pg_sequences where schemaname in (select nspname from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema') order by sequencename) q union all select 'database_properties' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select owner.rolname as owner,pg_encoding_to_char(d.encoding) as encoding,d.datcollate as collation,d.datctype as ctype,d.datlocprovider as locale_provider,coalesce(to_jsonb(d)->>'datlocale',to_jsonb(d)->>'daticulocale') as locale,to_jsonb(d)->>'daticurules' as icu_rules,d.datcollversion as collation_version,d.datallowconn as allow_connections,d.datistemplate as is_template,d.datconnlimit as connection_limit from pg_database d join pg_roles owner on owner.oid=d.datdba where d.datname=current_database()) q union all select 'database_acl' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select case when a.grantee=0 then 'PUBLIC' else grantee.rolname end as grantee,grantor.rolname as grantor,a.privilege_type,a.is_grantable from pg_database d cross join lateral aclexplode(coalesce(d.datacl,acldefault('d',d.datdba))) a left join pg_roles grantee on grantee.oid=a.grantee join pg_roles grantor on grantor.oid=a.grantor where d.datname=current_database() order by grantee,grantor,a.privilege_type,a.is_grantable) q union all select 'database_settings' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select 'CURRENT_DATABASE' as database_scope,case when s.setrole=0 then 'ALL_ROLES' else role.rolname end as role_name,setting.value as setting from pg_db_role_setting s left join pg_roles role on role.oid=s.setrole cross join lateral unnest(s.setconfig) as setting(value) where s.setdatabase=(select oid from pg_database where datname=current_database()) order by database_scope,role_name,setting.value) q union all select 'database_globalRoleSettings' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select 'ALL_DATABASES' as database_scope,case when s.setrole=0 then 'ALL_ROLES' else role.rolname end as role_name,setting.value as setting from pg_db_role_setting s left join pg_roles role on role.oid=s.setrole cross join lateral unnest(s.setconfig) as setting(value) where s.setdatabase=0 order by database_scope,role_name,setting.value) q union all select 'migrationLedger' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select version,name,checksum,applied_at from public.novalure_schema_migrations order by version) q union all select 'eventTriggers' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select evtname,evtevent,pg_get_userbyid(evtowner) as owner,evtenabled,evttags from pg_event_trigger order by evtname) q union all select 'publications' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select pubname,pg_get_userbyid(pubowner) as owner,puballtables,pubinsert,pubupdate,pubdelete,pubtruncate,pubviaroot from pg_publication order by pubname) q union all select 'largeObjectMetadata' as category,count(*)::int as objects,encode(public.digest(convert_to(coalesce(string_agg(to_jsonb(q)::text,E'\n' order by (to_jsonb(q)::text) collate "C"),''),'UTF8'),'sha256'),'hex') as sha256 from (select oid,pg_get_userbyid(lomowner) as owner,lomacl from pg_largeobject_metadata order by oid) q) c;
